import{_ as e,a as o,b as t,c as r}from"./chunks/kuka_theme_4.7PEyRC9o.js";import{_ as i,a as l,b as d,c as s,d as n,e as c,f as h,g as m,h as p,i as u,j as _}from"./chunks/sort_declarations.DU86DpOi.js";import{_ as f}from"./chunks/inlay_hints.BQUZLqE3.js";import{_ as g}from"./chunks/kuka_commands.D8cXdGAR.js";import{_ as k,o as b,c as S,a0 as A}from"./chunks/framework.QP0FkqbW.js";const I=JSON.parse('{"title":"🟢 Community Edition — Бесплатные базовые функции KUKA KRL Professional","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guide/community-features.md","filePath":"ru/guide/community-features.md"}'),q={name:"ru/guide/community-features.md"};function K(D,a,P,O,R,x){return b(),S("div",null,[...a[0]||(a[0]=[A('<h1 id="🟢-community-edition-—-бесплатные-базовые-функции-kuka-krl-professional" tabindex="-1">🟢 Community Edition — Бесплатные базовые функции KUKA KRL Professional <a class="header-anchor" href="#🟢-community-edition-—-бесплатные-базовые-функции-kuka-krl-professional" aria-label="Permalink to &quot;🟢 Community Edition — Бесплатные базовые функции KUKA KRL Professional&quot;">​</a></h1><p>Подробный обзор 15 бесплатных базовых функций расширения для разработчиков и инженеров-робототехников.</p><hr><h3 id="_1-синтаксическая-подсветка-krl-syntax-highlighting" tabindex="-1">1. Синтаксическая подсветка KRL (Syntax Highlighting) <a class="header-anchor" href="#_1-синтаксическая-подсветка-krl-syntax-highlighting" aria-label="Permalink to &quot;1. Синтаксическая подсветка KRL (Syntax Highlighting)&quot;">​</a></h3><p>Полный парсинг синтаксиса <code>.src</code>, <code>.dat</code>, <code>.sub</code>. Подсветка ключевых слов, типов данных (<code>INT</code>, <code>REAL</code>, <code>BOOL</code>, <code>E6POS</code>), системных переменных KSS 8.7 и FOLD-метаданных WorkVisual.</p><h4 id="до-установки-стандартныи-монотонныи-текст" tabindex="-1">До установки (стандартный монотонный текст): <a class="header-anchor" href="#до-установки-стандартныи-монотонныи-текст" aria-label="Permalink to &quot;До установки (стандартный монотонный текст):&quot;">​</a></h4><p><img src="'+e+'" alt="Syntax Highlighting До"></p><h4 id="после-установки-контрастная-инженерная-подсветка" tabindex="-1">После установки (Контрастная инженерная подсветка): <a class="header-anchor" href="#после-установки-контрастная-инженерная-подсветка" aria-label="Permalink to &quot;После установки (Контрастная инженерная подсветка):&quot;">​</a></h4><p><img src="'+i+'" alt="Syntax Highlighting После"></p><hr><h3 id="_2-эксклюзивные-темы-kuka-6-kuka-themes" tabindex="-1">2. Эксклюзивные темы KUKA (6 KUKA Themes) <a class="header-anchor" href="#_2-эксклюзивные-темы-kuka-6-kuka-themes" aria-label="Permalink to &quot;2. Эксклюзивные темы KUKA (6 KUKA Themes)&quot;">​</a></h3><p>6 профессиональных тем оформления, оптимизированных для промышленных ноутбуков и дисплеев SmartPAD:</p><ol><li><strong>Industrial Dark</strong> (фирменный стиль KUKA <code>#FF6600</code>)</li><li><strong>WorkVisual Dark</strong></li><li><strong>WorkVisual Light</strong></li><li><strong>Midnight OLED</strong></li><li><strong>Blueprint</strong></li><li><strong>Industrial Light</strong></li></ol><p><em>Переключение:</em> <code>Ctrl + K</code> <code>Ctrl + T</code></p><p><img src="'+l+'" alt="Theme 1"><img src="'+o+'" alt="Theme 2"><img src="'+t+'" alt="Theme 3"><img src="'+r+'" alt="Theme 4"></p><hr><h3 id="_3-умное-автодополнение-smart-autocomplete-kss-8-7" tabindex="-1">3. Умное автодополнение (Smart Autocomplete &amp; KSS 8.7) <a class="header-anchor" href="#_3-умное-автодополнение-smart-autocomplete-kss-8-7" aria-label="Permalink to &quot;3. Умное автодополнение (Smart Autocomplete &amp; KSS 8.7)&quot;">​</a></h3><p>Мгновенное выпадающее меню при вводе <code>$</code> с подсказками по 350+ системным переменным (<code>$POS_ACT</code>, <code>$VEL.CP</code>, <code>$BASE</code>, <code>$TOOL</code>, <code>$IN</code>, <code>$OUT</code>).</p><p><img src="'+d+'" alt="Smart Autocomplete Demo"></p><hr><h3 id="_4-мультиязычность-en-ru-tr" tabindex="-1">4. Мультиязычность (EN / RU / TR) <a class="header-anchor" href="#_4-мультиязычность-en-ru-tr" aria-label="Permalink to &quot;4. Мультиязычность (EN / RU / TR)&quot;">​</a></h3><p>Полная локализация интерфейса расширения, подсказок, меню команд и дашборда Control Center на русский, английский и турецкий языки.</p><hr><h3 id="_5-inlay-hints-для-сигналов-in-out-anin-anout" tabindex="-1">5. Inlay Hints для сигналов ($IN / $OUT / $ANIN / $ANOUT) <a class="header-anchor" href="#_5-inlay-hints-для-сигналов-in-out-anin-anout" aria-label="Permalink to &quot;5. Inlay Hints для сигналов ($IN / $OUT / $ANIN / $ANOUT)&quot;">​</a></h3><p>Виртуальные полупрозрачные подсказки имен сигналов прямо в коде (например, <code>$IN[1]</code> <code>: diPartReady</code>).</p><p><img src="'+f+'" alt="Inlay Hints Demo"></p><hr><h3 id="_6-всплывающая-информация-hover-info-read-write-status" tabindex="-1">6. Всплывающая информация (Hover Info &amp; Read/Write Status) <a class="header-anchor" href="#_6-всплывающая-информация-hover-info-read-write-status" aria-label="Permalink to &quot;6. Всплывающая информация (Hover Info &amp; Read/Write Status)&quot;">​</a></h3><p>При наведении курсора на системную переменную отображается описание из руководств KSS 8.7, тип данных и права доступа (<strong>Read-Only / Read-Write</strong>).</p><p><img src="'+s+'" alt="Hover Info Demo"></p><hr><h3 id="_7-кросс-фаиловая-навигация-src-↔-dat-go-to-definition" tabindex="-1">7. Кросс-файловая навигация (.src ↔ .dat Go-to-Definition) <a class="header-anchor" href="#_7-кросс-фаиловая-навигация-src-↔-dat-go-to-definition" aria-label="Permalink to &quot;7. Кросс-файловая навигация (.src ↔ .dat Go-to-Definition)&quot;">​</a></h3><p>Быстрый переход по <code>F12</code> / <code>Ctrl+Click</code> от использования точки/переменной в файле алгоритма <code>.src</code> к ее объявлению в <code>.dat</code>.</p><p><img src="'+n+'" alt="Go-to-Definition Demo"></p><hr><h3 id="_8-поиск-всех-ссылок-find-all-references-—-shift-alt-f12" tabindex="-1">8. Поиск всех ссылок (Find All References — <code>Shift+Alt+F12</code>) <a class="header-anchor" href="#_8-поиск-всех-ссылок-find-all-references-—-shift-alt-f12" aria-label="Permalink to &quot;8. Поиск всех ссылок (Find All References — `Shift+Alt+F12`)&quot;">​</a></h3><p>Показывает все места использования функции, точки или сигналов во всем проекте.</p><p><img src="'+c+'" alt="Find All References Demo"></p><hr><h3 id="_9-глобальныи-форматировщик-krl-code-formatter" tabindex="-1">9. Глобальный форматировщик KRL (Code Formatter) <a class="header-anchor" href="#_9-глобальныи-форматировщик-krl-code-formatter" aria-label="Permalink to &quot;9. Глобальный форматировщик KRL (Code Formatter)&quot;">​</a></h3><p>Автоматическое выравнивание знаков <code>=</code> и вложенности блоков <code>IF/FOR/WHILE</code> по нажатию <code>Shift + Alt + F</code>.</p><p><img src="'+h+'" alt="Code Formatter Demo"></p><hr><h3 id="_10-быстрое-сворачивание-разворачивание-fold-quick-fold-toolbar" tabindex="-1">10. Быстрое сворачивание / разворачивание FOLD (Quick Fold Toolbar) <a class="header-anchor" href="#_10-быстрое-сворачивание-разворачивание-fold-quick-fold-toolbar" aria-label="Permalink to &quot;10. Быстрое сворачивание / разворачивание FOLD (Quick Fold Toolbar)&quot;">​</a></h3><p>Иконки 🙈 (<code>krl.foldAll</code>) и 📖 (<code>krl.unfoldAll</code>) в тулбаре для сжатия и разворачивания всех блоков FOLD.</p><p><img src="'+m+'" alt="Quick Fold Toolbar Demo"></p><hr><h3 id="_11-полное-дерево-команд-kuka-commands" tabindex="-1">11. Полное дерево команд KUKA COMMANDS <a class="header-anchor" href="#_11-полное-дерево-команд-kuka-commands" aria-label="Permalink to &quot;11. Полное дерево команд KUKA COMMANDS&quot;">​</a></h3><p>Удобная боковая панель с категоризированным деревом всех команд расширения.</p><p><img src="'+g+'" alt="KUKA COMMANDS Demo"></p><hr><h3 id="_12-панель-сигналов-krl-i-o-signals" tabindex="-1">12. Панель сигналов KRL I/O Signals <a class="header-anchor" href="#_12-панель-сигналов-krl-i-o-signals" aria-label="Permalink to &quot;12. Панель сигналов KRL I/O Signals&quot;">​</a></h3><p>Панель сигналов входов/выходов с быстрой фильтрацией и поиском.</p><p><img src="'+p+'" alt="KRL I/O Signals Demo"></p><hr><h3 id="_13-очистка-неиспользуемых-переменных-unused-variable-cleaner" tabindex="-1">13. Очистка неиспользуемых переменных (Unused Variable Cleaner) <a class="header-anchor" href="#_13-очистка-неиспользуемых-переменных-unused-variable-cleaner" aria-label="Permalink to &quot;13. Очистка неиспользуемых переменных (Unused Variable Cleaner)&quot;">​</a></h3><p>Удаление ненужных объявлений <code>DECL</code> из <code>.dat</code> файлов без нарушения структуры FOLD.</p><hr><h3 id="_14-очиститель-git-метаданных-workvisual-git-metadata-cleaner" tabindex="-1">14. Очиститель Git-метаданных WorkVisual (Git Metadata Cleaner) <a class="header-anchor" href="#_14-очиститель-git-метаданных-workvisual-git-metadata-cleaner" aria-label="Permalink to &quot;14. Очиститель Git-метаданных WorkVisual (Git Metadata Cleaner)&quot;">​</a></h3><p>Срезает заголовки <code>&amp;ACCESS</code>, <code>&amp;REL</code>, <code>&amp;PARAM</code> для создания чистых коммитов в Git.</p><p><img src="'+u+'" alt="Git Metadata Cleaner Demo"></p><hr><h3 id="_15-сортировка-объявлении-sort-declarations" tabindex="-1">15. Сортировка объявлений (Sort Declarations) <a class="header-anchor" href="#_15-сортировка-объявлении-sort-declarations" aria-label="Permalink to &quot;15. Сортировка объявлений (Sort Declarations)&quot;">​</a></h3><p>Сортировка типов переменных (<code>INT</code>, <code>REAL</code>, <code>BOOL</code>, <code>E6POS</code>) в <code>.dat</code> файлах.</p><p><img src="'+_+'" alt="Sort Declarations Demo"></p>',65)])])}const y=k(q,[["render",K]]);export{I as __pageData,y as default};
